INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES ("お礼にいただいたお弁当が、\nあまりにもおいしくて……", 1, 0, 0, 142, 1, 142012, 11, 1, 10, 0);
