INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES ("……でも。\n今回の冒険で、夢見ることは\n大きな力だと知りましたから。", 1, 0, 0, 142, 1, 142024, 11, 1, 10, 0);
